// StiltzkinsBag.Core/Models/FieldItemScanner.cs
//
// Scans all FF9 Steam field script files (.eb.bytes) and returns a per-item count
// of finite field instances (chests, hidden items, scripted item rewards).
//
// Two entry points:
//
//   ScanArchive(archivePath)
//     Opens p0data7.bin via UnityArchiver, iterates all US-locale field files,
//     runs FieldParser.FindItemLocations on each, and accumulates counts.
//
//   ScanFiles(IEnumerable<(string name, byte[] bytes)>)
//     Lower-level: scans a caller-supplied collection of (filename, bytes) pairs.
//     Used by tests to scan pre-committed .bytes files without a live archive.
//
// Counting rules:
//   • Only DirectItem and TreasureItem locations are counted (not TextSync / DirectGil).
//   • Only item IDs 0–255 are counted (< 256 = plain item; 256–511 = cards, 512+ = gil).
//   • Each unique (file, byte-offset) pair counts as exactly ONE item instance.
//     This correctly de-duplicates AddItem calls that appear in multiple branch arms
//     of the same if-else block, because they each occupy different byte offsets.
//   • TextSync locations (SetTextVariable display pairs) are skipped — they are
//     not additional item instances.
//   • The returned dictionary maps item ID -> count of distinct field instances.
//     Items not found in any field file are absent from the dictionary.
//
// Archive path within p0data7.bin:
//   assets/resources/commonasset/eventengine/eventbinary/field/us/
//   All files in this folder have the .eb.bytes extension and are US-locale field scripts.
//   Entries for other locales (es, fr, gr, it, jp, uk) are skipped to avoid double-counting.
//
// False positives:
//   FieldParser.FindItemLocations can return DirectItem locations with IDs > 255
//   (e.g., 10008, 18241) because the 0x48 opcode byte can appear inside variable
//   expressions of unrelated opcodes. These are filtered out by the < 256 check.

using System;
using System.Collections.Generic;
using System.Linq;
using StiltzkinsBag.Core.Parsing;
using StiltzkinsBag.Parsing;

namespace StiltzkinsBag.Core.Models;

/// <summary>
/// Scans FF9 Steam field script files to count per-item finite field instances.
/// </summary>
public static class FieldItemScanner
{
    /// <summary>
    /// Path suffix inside p0data7.bin for US-locale field scripts.
    /// UnityArchiver.ExtractByPath matches on the leaf filename, so the locale
    /// folder prefix is embedded in the path for correctness.
    /// </summary>
    private const string FieldUsPrefix = "field/us/";

    // ── Public entry points ───────────────────────────────────────────────────

    /// <summary>
    /// Opens p0data7.bin (or any equivalent Unity archive containing field scripts)
    /// and scans all US-locale field files.
    /// </summary>
    /// <param name="archivePath">Full path to p0data7.bin.</param>
    /// <returns>
    /// Dictionary mapping item ID (0–255) to the number of distinct field instances
    /// (unique file × offset pairs). Items with zero instances are absent.
    /// </returns>
    /// <exception cref="ArgumentNullException"><paramref name="archivePath"/> is null.</exception>
    /// <exception cref="System.IO.FileNotFoundException">Archive not found.</exception>
    public static IReadOnlyDictionary<int, int> ScanArchive(string archivePath)
    {
        ArgumentNullException.ThrowIfNull(archivePath);

        var counts = new Dictionary<int, int>();

        using var archive = UnityArchiver.Open(archivePath);

        // Archive entry names are leaf names as stored in the asset bundle (TextAsset).
        // The Unity convention for p0data7.bin is that field script TextAsset entries
        // are named "evt_XXX.eb" (WITHOUT the ".bytes" extension) or sometimes include
        // ".eb.bytes". We filter the same way FieldItemRandomizer does: by "evt_" prefix.
        //
        // All locales (es, fr, gr, it, jp, uk, us) share byte-identical bytecode — only
        // AT_TEXT string IDs differ. Since UnityArchiver returns distinct leaf names and
        // field files from different locales share the same leaf name, each unique name
        // is extracted once (the first occurrence in the archive, which is 'us').
        // This matches the FieldItemRandomizer's deduplication approach.
        var distinctFieldNames = archive.GetFileNames()
            .Where(n => n.StartsWith("evt_", StringComparison.OrdinalIgnoreCase))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();

        foreach (string name in distinctFieldNames)
        {

            byte[] bytes;
            try { bytes = archive.Extract(name); }
            catch { continue; } // skip unreadable entries

            ScanSingleFile(name, bytes, counts);
        }

        return counts;
    }

    /// <summary>
    /// Scans a caller-supplied collection of (filename, bytes) pairs.
    /// Useful for tests using pre-committed .bytes files without a live archive.
    /// </summary>
    /// <param name="files">
    /// Each tuple: (filename for diagnostics, .eb.bytes content).
    /// </param>
    public static IReadOnlyDictionary<int, int> ScanFiles(
        IEnumerable<(string Name, byte[] Bytes)> files)
    {
        ArgumentNullException.ThrowIfNull(files);

        var counts = new Dictionary<int, int>();

        foreach (var (name, bytes) in files)
        {
            if (bytes is null || bytes.Length == 0) continue;
            ScanSingleFile(name, bytes, counts);
        }

        return counts;
    }

    // ── Private helpers ───────────────────────────────────────────────────────

    /// <summary>
    /// Parses one .eb.bytes file and accumulates item counts into <paramref name="counts"/>.
    /// Each unique byte offset that yields a valid item ID (0–255) adds 1 to that item's count.
    /// </summary>
    private static void ScanSingleFile(
        string filename,
        byte[] bytes,
        Dictionary<int, int> counts)
    {
        IReadOnlyList<FieldItemLocation> locations;
        try
        {
            locations = FieldParser.FindItemLocations(bytes);
        }
        catch
        {
            // Malformed file — skip cleanly. FieldParser validates structure.
            return;
        }

        foreach (FieldItemLocation loc in locations)
        {
            // Only count actual item instances — skip TextSync and DirectGil.
            if (loc.LocationKind != FieldLocationKind.DirectItem &&
                loc.LocationKind != FieldLocationKind.TreasureItem)
                continue;

            // For TreasureItem: only count plain item IDs (< 512).
            // Values 512–999 = cards, 1000–29998 = gil, 29999 = disabled.
            int itemId = loc.CurrentValue;
            if (loc.LocationKind == FieldLocationKind.TreasureItem)
            {
                if (!loc.TreasureIsItem) continue; // card, gil, or disabled
                // TreasureIsItem guarantees currentValue < 512
            }

            // Filter to valid item ID range (0–255).
            // DirectItem false-positives (opcode byte collisions) produce IDs > 255.
            if (itemId < 0 || itemId > 255) continue;

            counts[itemId] = counts.TryGetValue(itemId, out int existing)
                ? existing + 1
                : 1;
        }
    }
}

// StiltzkinsBag.Core/Models/VanillaObtainabilityData.cs
//
// Static, hardcoded repository of every vanilla item source in FFIX PC (Steam).
// This is the ground truth used by VanillaItemCatalog to classify items and build
// the master obtainability dictionary.
//
// Sources encoded here:
//   • Enemy drops and steals — classified as Normal (repeatable) or Boss-only (one-time)
//   • Chocograph rewards — finite counts per chocograph (24 total)
//   • Treno Auction House — repeatable auctions vs. one-time lots
//   • Friendly Monster chain — 9 one-time encounters (Mu -> Yan)
//   • Ragtime Mouse — 1 one-time reward
//
// NOT encoded here (handled elsewhere):
//   • Shops (ShopItems.csv — all infinite, loaded at runtime)
//   • Synthesis recipes (Synthesis.csv — loaded at runtime; depends on ingredient availability)
//   • Field chests and scripted item rewards (FieldItemScanner — runtime binary scan)
//   • Stiltzkin encounters (Phase 5.9)
//
// Methodology for enemy data:
//   Source: "Final Fantasy IX Reference Guide - Stolen Items + Blue Magic.csv"
//   • Normal enemy items = steals + drops from enemies of type Normal or Ragtime Mouse
//   • Boss-only items    = steals + drops from Boss/Stage/Prison Cage/Crystal types
//                         MINUS anything already in Normal set or any shop
//   Name variants resolved manually (Pheonix Down->Phoenix Down, Wedge Wing->Wing Edge, etc.)
//
// Methodology for chocograph data:
//   Source: "Final Fantasy IX Reference Guide - Chocobo Side Quests.csv"
//   Counts represent total instances across all 24 chocographs combined.
//   Ability unlocks (Reef/Mountain/Ocean/Sky) and cards are excluded.
//
// Methodology for auction data:
//   Source: "Final Fantasy IX Reference Guide - Treno Auction House.csv"
//   Key items / resellable quest items (Griffin's Heart, Doga's Artifact, etc.) excluded.
//
// All item IDs are verified against Items.csv (IDs 0–255).

using System.Collections.Generic;

namespace StiltzkinsBag.Core.Models;

/// <summary>
/// Static repository of all vanilla item obtainability sources that require
/// hardcoded game knowledge (enemy tables, sidequest rewards, etc.).
/// </summary>
public static class VanillaObtainabilityData
{
    // ── Enemy sources ──────────────────────────────────────────────────────────

    /// <summary>
    /// Item IDs obtainable from Normal-type or Stage-type enemies (steals + drops).
    /// Normal enemies are repeatable — any item in this set has an infinite source.
    ///
    /// Note: Ragtime Mouse is classified as Normal in the enemy guide; its reward
    /// (Protect Ring ID 209) is actually one-time, but since it also appears in the
    /// Normal enemy set it will be flagged HasNormalEnemySource = true. The Protect
    /// Ring is separately finite-capped by the field scanner (it is awarded via
    /// scripted AddItem in Chocobo's Forest after Ragtime completion).
    /// </summary>
    public static readonly IReadOnlySet<int> NormalEnemyItemIds = new HashSet<int>
    {
         48,  // Kaiser Knuckles
         80,  // Needle Fork
         86,  // Rising Sun
         87,  // Wing Edge
        104,  // Mythril Gloves
        141,  // Gold Helm
        154,  // Mythril Vest
        188,  // Dragon Mail
        209,  // Protect Ring  (Ragtime Mouse — classified Normal in guide)
        224,  // Garnet
        225,  // Amethyst
        231,  // Peridot
        232,  // Sapphire
        233,  // Opal
        234,  // Topaz
        235,  // Lapis Lazuli
        236,  // Potion
        237,  // Hi-Potion
        238,  // Ether
        239,  // Elixir
        240,  // Phoenix Down
        241,  // Echo Screen
        242,  // Soft
        243,  // Antidote
        244,  // Eye Drops
        245,  // Magic Tag
        246,  // Vaccine
        247,  // Remedy
        248,  // Annoyntment
        249,  // Phoenix Pinion
        253,  // Tent
        254,  // Ore
    };

    /// <summary>
    /// Item IDs obtainable ONLY from Boss-type enemies (Boss/Stage/Prison Cage/Crystal).
    /// These items are NOT in any shop and NOT from Normal enemies — making them
    /// finite (each boss can only be fought once).
    ///
    /// Note: Stage-type enemies (e.g. King Leo at the play) yield items but are
    /// effectively one-time and are treated here as boss-like for classification.
    /// </summary>
    public static readonly IReadOnlySet<int> BossOnlyItemIds = new HashSet<int>
    {
         13,  // Masamune
         19,  // Blood Sword
         49,  // Duel Claws
        109,  // Genji Gloves
        146,  // Genji Helmet
        147,  // Grand Helm
        166,  // Rubber Suit
        171,  // Glutton's Robe
        172,  // White Robe
        173,  // Black Robe
        174,  // Light Robe
        175,  // Robe of Lords
        189,  // Genji Armor
        191,  // Grand Armor
        196,  // Feather Boots   (also Auction repeatable — effectively infinite overall)
        197,  // Battle Boots
        198,  // Running Shoes
        201,  // Black Belt
        205,  // Reflect Ring    (also Auction one-time — catalog totals both)
        208,  // Rebirth Ring    (also Chocograph #24 — catalog totals both)
        210,  // Pumice Piece    (also Chocograph #22 — catalog totals both)
        211,  // Pumice
        250,  // Dark Matter     (also Auction one-time — catalog totals both)
    };

    // ── Chocograph rewards ────────────────────────────────────────────────────

    /// <summary>
    /// Total item counts across all 24 chocographs combined.
    /// Each chocograph is a one-time event — these counts are finite.
    ///
    /// Counts verified from: Final Fantasy IX Reference Guide - Chocobo Side Quests.csv
    /// Cards, ability unlocks (Reef/Mountain/Ocean/Sky), and quest-only items are excluded.
    /// Plural typos in the source CSV (Potions, Hi-Potions, Antidotes, Cotton Robes) resolved.
    /// </summary>
    public static readonly IReadOnlyDictionary<int, int> ChocographItemCounts = new Dictionary<int, int>
    {
        {  48, 1 },   // Kaiser Knuckles    (Chocograph #15)
        {  74, 1 },   // Oak Staff          (Chocograph #11)
        {  77, 1 },   // High Mage Staff    (Chocograph #13)
        {  86, 8 },   // Rising Sun         (Chocograph #11)
        {  87, 13 },  // Wing Edge          (Chocos #3, #13)
        {  97, 1 },   // Jade Armlet        (Chocograph #3)
        { 106, 1 },   // Diamond Gloves     (Chocograph #5)
        { 168, 1 },   // Cotton Robe        (Chocograph #2)
        { 170, 1 },   // Magician Robe      (Chocograph #10)
        { 172, 1 },   // White Robe         (Chocograph #17)
        { 174, 1 },   // Light Robe         (Chocograph #18)
        { 183, 1 },   // Shield Armor       (Chocograph #8)
        { 184, 1 },   // Demon's Mail       (Chocograph #16)
        { 189, 1 },   // Genji Armor        (Chocograph #21)
        { 194, 2 },   // Germinas Boots     (Chocograph #1)
        { 196, 1 },   // Feather Boots      (Chocograph #9)
        { 208, 1 },   // Rebirth Ring       (Chocograph #24)
        { 210, 1 },   // Pumice Piece       (Chocograph #22)
        { 221, 1 },   // Ribbon             (Chocograph #24)
        { 224, 16 },  // Garnet             (Chocos #21, #5 area)
        { 225, 34 },  // Amethyst           (Chocos #21, #24)
        { 227, 1 },   // Diamond            (Chocograph #17)
        { 231, 23 },  // Peridot            (Chocos #5, #19)
        { 232, 26 },  // Sapphire           (Chocos #19, #22)
        { 233, 23 },  // Opal               (Chocos #16, #19)
        { 234, 19 },  // Topaz              (Chocograph #19)
        { 236, 78 },  // Potion             (Chocos #2 as "Potions", #8, #23)
        { 237, 18 },  // Hi-Potion          (Chocos #1, #2 as "Hi-Potions", #6)
        { 238, 28 },  // Ether              (Chocos #1, #7, #9, #13)
        { 239, 6 },   // Elixir             (Chocos #1, #11)
        { 240, 21 },  // Phoenix Down       (Chocos #5, #15, as "Phoenix Down")
        { 241, 7 },   // Echo Screen        (Chocograph #6)
        { 242, 6 },   // Soft               (Chocograph #9)
        { 243, 10 },  // Antidote           (Chocograph #3 as "Antidotes")
        { 245, 6 },   // Magic Tag          (Chocograph #8)
        { 247, 4 },   // Remedy             (Chocograph #11)
        { 248, 15 },  // Annoyntment        (Chocograph #23)
        { 249, 24 },  // Phoenix Pinion     (Chocos #5, #15)
        { 253, 3 },   // Tent               (Chocos #2 as "Tents", #6)
        { 254, 58 },  // Ore                (Chocos #15, #16, #18)
    };

    // ── Treno Auction House ────────────────────────────────────────────────────

    /// <summary>
    /// Items available at the Treno Auction House that can be won multiple times.
    /// These are effectively infinite obtainability sources.
    ///
    /// Includes: Magician Robe (170), Fairy Earrings (214), Madain's Ring (203),
    ///           Pearl Rouge (216), Elixir (239), Feather Boots (196), Anklet (199),
    ///           Promist Ring (207).
    ///
    /// Note: Feather Boots also appear as a boss drop and chocograph reward.
    ///       Elixir also appears as a friendly monster reward.
    ///       The infinite auction source dominates — these will be int.MaxValue overall.
    /// </summary>
    public static readonly IReadOnlySet<int> AuctionRepeatableItemIds = new HashSet<int>
    {
        170,  // Magician Robe
        196,  // Feather Boots
        199,  // Anklet
        203,  // Madain's Ring
        207,  // Promist Ring
        214,  // Fairy Earrings
        216,  // Pearl Rouge
        239,  // Elixir
    };

    /// <summary>
    /// Items available at the Treno Auction House exactly once.
    /// Finite — each appears at most once per playthrough.
    ///
    /// Includes: Reflect Ring (205), Dark Matter (250), Thief Gloves (98), Ribbon (221).
    /// Note: Reflect Ring also appears as a boss drop.
    ///       Ribbon also appears in Chocograph #24 and Stiltzkin's final reward (Phase 5.9).
    ///       Dark Matter also appears as a boss drop.
    ///       The catalog sums all finite instances.
    /// </summary>
    public static readonly IReadOnlySet<int> AuctionOneTimeItemIds = new HashSet<int>
    {
         98,  // Thief Gloves
        205,  // Reflect Ring
        221,  // Ribbon
        250,  // Dark Matter
    };

    // ── Friendly Monster chain ─────────────────────────────────────────────────

    /// <summary>
    /// Item IDs rewarded by the 9-encounter Friendly Monster chain (Mu -> Yan).
    /// Each reward is a one-time gift from completing one link in the chain.
    ///
    /// Note: Several rewards (Potion, Hi-Potion, Ether, Elixir) are also available
    /// from repeatable sources, so those specific item IDs will be int.MaxValue overall.
    /// The gems (Emerald/Moonstone/Lapis Lazuli/Diamond) are one-time here.
    /// </summary>
    public static readonly IReadOnlySet<int> FriendlyMonsterItemIds = new HashSet<int>
    {
        236,  // Potion        (Mu)
        237,  // Hi-Potion     (Ghost)
        238,  // Ether         (Lady Bug)
        239,  // Elixir        (Yeti)
        228,  // Emerald       (Nymph)
        229,  // Moonstone     (Jabberwock)
        235,  // Lapis Lazuli  (Feather Circle)
        227,  // Diamond       (Garuda)
        204,  // Rosetta Ring  (Yan)
    };

    // ── Ragtime Mouse ─────────────────────────────────────────────────────────

    /// <summary>
    /// The single reward for completing all 16 Ragtime Mouse quiz questions.
    /// One-time per playthrough.
    ///
    /// Protect Ring (ID 209) is also classifiable as a Normal enemy drop in the
    /// guide (Ragtime Mouse's enemy type = Normal). VanillaItemCatalog will
    /// add 1 to its finite field count rather than treating it as infinite.
    /// </summary>
    public static readonly IReadOnlySet<int> RagtimeMouseItemIds = new HashSet<int>
    {
        209,  // Protect Ring  (Ragtime Mouse quiz completion reward)
    };

    // ── Stiltzkin encounters ───────────────────────────────────────────────────
    // Phase 5.9 — intentionally deferred.
    // StiltzkinRandomizer will register Stiltzkin's 8 locations and their items here,
    // or pass them directly to VanillaItemCatalog via its own scanner.
}

